package com.proxyslabs.haruna.image
import java.io.File
fun main(args:Array<String>){check(NezumiImageNative.available);val root=File(args[0]);val first=NezumiImageNative.create();check(first>0);check(NezumiImageNative.validateFiles(NezumiPackage.graphFiles(root)));check(NezumiImageNative.loadCpu(first,root.path));check(NezumiImageNative.isLoaded(first));NezumiImageNative.cancel(first);check(NezumiImageNative.generateRgb(first,"a red apple","",5,424242)==null);NezumiImageNative.destroy(first);NezumiImageNative.destroy(first);check(!NezumiImageNative.isLoaded(first));val second=NezumiImageNative.create();check(second>first);NezumiImageNative.cancel(first);check(NezumiImageNative.loadCpu(second,root.path));check(NezumiImageNative.isLoaded(second));NezumiImageNative.unload(second);check(!NezumiImageNative.isLoaded(second));NezumiImageNative.destroy(second);val third=NezumiImageNative.create();check(NezumiImageNative.loadCpu(third,root.path));var output:ByteArray?=null;val thread=Thread{output=NezumiImageNative.generateRgb(third,"a red apple","",5,424242)};thread.start();val deadline=System.nanoTime()+60_000_000_000L;while(thread.isAlive&&NezumiImageNative.progress(third)[0]<2&&System.nanoTime()<deadline)Thread.sleep(1);NezumiImageNative.cancel(third);thread.join(60000);check(!thread.isAlive&&output==null);NezumiImageNative.destroy(third);println("PASS actual host JNI cooperative cancellation after generation starts");println("PASS actual host JNI: FlatBuffer validation, CPU load, cancel before generation, destroy idempotency, stale handle, new handle load, unload")}
